app.post('/api/p2p/buy',async(req,res)=>{ const{buyerId,tradeId}=req.body; const[t]=await db.query("SELECT * FROM p2p_trades WHERE id=? AND status='open'",[tradeId]); if(!t.length) return res.status(400).json({error:"Sold"}); const[buyer]=await db.query("SELECT balance FROM users WHERE id=?",[buyerId]); if(buyer[0].balance < t[0].price) return res.status(400).json({error:"Insufficient investment wallet"}); await db.query("UPDATE users SET balance=balance-? WHERE id=?",[t[0].price,buyerId]); await db.query("UPDATE users SET balance=balance+? WHERE id=?",[t[0].price*0.95,t[0].sellerId]); await db.query("UPDATE p2p_trades SET status='sold', buyerId=? WHERE id=?",[buyerId,tradeId]); // transfer invest
  const[inv]=await db.query("SELECT * FROM investments WHERE userId=? AND club=? AND status='selling' LIMIT 1",[t[0].sellerId,t[0].club]); if(inv.length){ await db.query("INSERT INTO investments (userId,club,amount,rate,lockDays,startDate) VALUES (?,?,?,?,?,?)",[buyerId,inv[0].club,inv[0].amount,inv[0].rate,inv[0].lockDays,inv[0].startDate]); }
  res.json({ok:1}); });
