app.post('/api/deposit',async(req,res)=>{ try{ const {userId, amount, airtelNo, screenshot} = req.body; if(!screenshot || screenshot.length < 100) return res.status(400).json({error:"Upload proof!"}); if(parseInt(amount) < 2000) return res.status(400).json({error:"Min 2000"}); const [dup] = await db.query("SELECT id FROM deposits WHERE screenshot=? LIMIT 1", [screenshot]); if(dup.length > 0) return res.status(400).json({error:"Screenshot already used!"}); const[u]=await db.query("SELECT phone FROM users WHERE id=?",[userId]); await db.query("INSERT INTO deposits (userId,phone,amount,airtelNo,screenshot) VALUES (?,?,?,?,?)",[userId, u[0]?u[0].phone:"", parseInt(amount), airtelNo, screenshot]); sendAdminAlert(`🔔 DEPOSIT ${u[0]?u[0].phone:""} ${amount}`); res.json({ok:1}); }catch(e){ res.status(400).json({error:e.message}) } });
