app.post('/api/withdraw',async(req,res)=>{ const[inv]=await db.query("SELECT * FROM investments WHERE userId=?",[req.body.userId]); let total=0; let now=new Date(); for(let i of inv){let d=Math.floor((now-new Date(i.startDate))/(1000*60*60*24)); let rate=i.rate||10; total+=Math.floor((i.amount||0)*rate/100*d);} const[w]=await db.query("SELECT COALESCE(SUM(amount),0) as s FROM withdrawals WHERE userId=? AND status IN ('pending','approved')",[req.body.userId]); let avail=total-w[0].s; if(req.body.amount>avail) return res.status(400).json({error:"Only "+avail+" available"}); if(req.body.amount<5000) return res.status(400).json({error:"Min 5000"}); await db.query("INSERT INTO withdrawals (userId,amount,type) VALUES (?,?,'interest')",[req.body.userId,req.body.amount]); sendAdminAlert(`💸 WITHDRAW ${req.body.userId} ${req.body.amount}`); res.json({ok:1}); });
app.post('/api/transfer',async(req,res)=>{ const{userId,from,to,amount}=req.body; if(from==='game' && to==='invest'){ const[u]=await db.query("SELECT gameBalance FROM users WHERE id=?",[userId]); if(u[0].gameBalance < amount) return res.status(400).json({error:"No game balance"}); await db.query("UPDATE users SET gameBalance=gameBalance-?, balance=balance+? WHERE id=?",[amount,amount,userId]); res.json({ok:1}); } else { res.status(400).json({error:"Invalid"}); } });
