app.get('/api/admin/stats',async(req,res)=>{ if(req.query.key!==ADMIN_KEY) return res.status(401).json({}); try{ let today=0,totalDep=0,pendingW=0,users=0,invested=0,pendingD=0,pendingWCount=0; try{ const[r]=await db.query("SELECT COALESCE(SUM(amount),0) as s FROM deposits WHERE status='approved' AND DATE(createdAt)=CURDATE()"); today=r[0].s; }catch(e){} try{ const[r]=await db.query("SELECT COALESCE(SUM(amount),0) as s FROM deposits WHERE status='approved'"); totalDep=r[0].s; }catch(e){} try{ const[r]=await db.query("SELECT COALESCE(SUM(amount),0) as s FROM withdrawals WHERE status='pending'"); pendingW=r[0].s; }catch(e){} try{ const[r]=await db.query("SELECT COUNT(*) as c FROM withdrawals WHERE status='pending'"); pendingWCount=r[0].c; }catch(e){} try{ const[r]=await db.query("SELECT COUNT(*) as c FROM users"); users=r[0].c; }catch(e){} try{ const[r]=await db.query("SELECT COALESCE(SUM(amount),0) as s FROM investments"); invested=r[0].s; }catch(e){} try{ const[r]=await db.query("SELECT COUNT(*) as c FROM deposits WHERE status='pending'"); pendingD=r[0].c; }catch(e){} res.json({today,totalDep,pendingW,users,invested,pendingD,pendingWCount}); }catch(e){ res.json({today:0,totalDep:0,pendingW:0,users:0,invested:0,pendingD:0}); } });
